SELECT budget, location, ROUND(budget, 2) AS budget_rounded
FROM departments
WHERE (budget BETWEEN 1251000 AND 3412000 AND budget < 3634000) OR location IN ('New York', 'Berlin');

select level, total_salary, pct_l1
from (
    select level, sum(salary) as total_salary, round((100 * sum(case when level = 'L1' then 1 else 0 end)) / count(*), 1) as pct_l1
    from employees
    group by level
) as sub
where pct_l1 > 61
order by total_salary desc;

select customer_id, max_balance, min_balance
from (
    select customer_id, max(balance) as max_balance, min(balance) as min_balance
    from accounts
    group by customer_id
) as t
where max_balance >= 55000
order by customer_id desc;

SELECT * FROM (SELECT DATE_FORMAT(signup_date, 'yyyy-MM') AS signup_month, city, credit_limit FROM customers WHERE age != 48)
PIVOT (COUNT(credit_limit) FOR city IN ('Singapore', 'Tokyo', 'Bangkok'))
ORDER BY signup_month;

select supplier_id, sum(stock_qty) as total_stock_qty, round(sum(stock_qty) * 100.0 / sum(sum(stock_qty)) over (), 2) as pct_of_total
from products
group by supplier_id;

SELECT order_id, SUM(quantity) AS total_quantity, ROUND(SUM(quantity) * 100.0 / SUM(SUM(quantity)) OVER (), 2) AS pct_of_total
FROM order_items
GROUP BY order_id;

SELECT product_id, SUM(quantity) total_quantity, ROUND(SUM(quantity) * 100.0 / SUM(SUM(quantity)) OVER (), 2) AS pct_of_total
FROM order_items
GROUP BY product_id;

select *
from (
    select *, rank() over (partition by level order by salary desc) as rn
    from employees
) t
where rn = 1

SELECT *, ADD_MONTHS(sale_date, 12) AS sale_date_plus_months
FROM store_sales
WHERE sale_date > '2025-03-20';

select sale_month, stddev_revenue
from (
    select month(sale_date) sale_month, round(stddev(revenue), 2) stddev_revenue
    from store_sales
    group by month(sale_date)
) t
where stddev_revenue > 20
order by stddev_revenue desc, sale_month desc;

SELECT id, stock_qty, ROUND(price * 0.9, 2) AS price_scaled
FROM products
WHERE cost >= 560 AND category NOT IN ('Home', 'Books', 'Sports') AND category = 'Home';

SELECT ss.id, ss.sale_date
FROM store_sales ss
WHERE ss.sale_date >= '2024-01-09' AND ss.store_id NOT IN (SELECT id FROM stores WHERE sqft < 4493);

SELECT id, rating, LEAD(rating, 2) OVER (ORDER BY rating, id) next_rating
FROM suppliers
WHERE city IS NULL;

select *, case when status in ('CLOSED', 'OPEN') then 'Priority' else 'Other' end status_group
from accounts
where customer_id is null;

SELECT CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(brand))) AS brand_values, MIN(launch_date) AS min_launch_date
FROM products
WHERE launch_date > '2024-06-01' AND category = 'Home';

SELECT *
FROM store_sales
WHERE (product_id = 1 AND revenue > 3400) OR product_id = 2;

select id, store_id, last_restock
from (
    select
        id,
        store_id,
        last_restock,
        rank() over (partition by store_id order by last_restock desc) as rnk
    from inventory
) as ranked
where rnk = 1;

select id, plan, start_date
from (
    select
        id,
        plan,
        start_date,
        row_number() over (partition by plan order by start_date desc, id) as rnk
    from subscriptions
) as t
where rnk = 1;

SELECT *
FROM (
    SELECT *, DENSE_RANK() OVER (PARTITION BY store_id ORDER BY order_date DESC) AS pos
    FROM orders
) AS t
WHERE pos <= 3;

SELECT *
FROM (
    SELECT *, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY sale_date DESC) row_num
    FROM store_sales
) r
WHERE row_num <= 1;

select *
from (
    select *, row_number() over (partition by dept_id order by hire_date, id) as rnk
    from employees
) as ranked
where rnk <= 3;

SELECT *
FROM (
    SELECT *, RANK() OVER (PARTITION BY page ORDER BY event_time) rn
    FROM web_events
) t
WHERE rn <= 2;

select
    id,
    store_id,
    sale_date,
    revenue
from (
    select *, row_number() over (partition by store_id order by sale_date desc, id) as rn
    from store_sales
) as t
where rn <= 5;

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY amount DESC, id) AS row_num
    FROM transactions
) AS t
WHERE row_num <= 3;

SELECT id, city, rating
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating DESC, id) AS rn
    FROM suppliers
) AS r
WHERE rn <= 2;

select id, country, started_at
from (
    select
        id,
        country,
        started_at,
        rank() over (partition by country order by started_at desc) as row_num
    from sessions
) as ranked
where row_num = 1;

select *
from (
    select *, row_number() over (partition by city order by sqft desc, id) as pos
    from stores
) as t
where pos <= 2

select id, order_id, unit_price
from (
    select *, row_number() over (partition by order_id order by unit_price desc, id) as row_num
    from order_items
) as r
where row_num <= 2;

select *
from (
    select
        id,
        browser,
        started_at,
        rank() over (partition by browser order by started_at desc) as rnk
    from sessions
) as ranked
where rnk <= 5;

SELECT id, account_type
FROM accounts
QUALIFY RANK() OVER (PARTITION BY customer_id ORDER BY balance DESC) = 1;

SELECT ROUND(STDDEV(quantity), 2) AS stddev_quantity, MAX(quantity) AS max_quantity
FROM inventory
WHERE product_id = 2;

SELECT MIN(amount) AS min_amount
FROM orders
WHERE shipping_fee < 25;

SELECT MIN(amount) min_amount
FROM payments
WHERE method = 'cash';

select budget_bucket, budget_count, cnt
from (
    select case when budget >= 3640000 then 'high' when budget >= 1091000 then 'mid' else 'low' end as budget_bucket, count(budget) as budget_count, count(*) as cnt
    from departments
    group by case when budget >= 3640000 then 'high' when budget >= 1091000 then 'mid' else 'low' end
) as s
where cnt > 6;

select *
from (
    select year(launch_date) as launch_year, avg(stock_qty) as avg_stock_qty, sort_array(collect_set(brand)) as brand_list
    from products
    group by year(launch_date)
) as s
where avg_stock_qty >= 170;

SELECT DISTINCT job_title
FROM employees
WHERE NOT is_remote;

SELECT id, customer_id, CONCAT(account_type, ' ', status) account_type_status
FROM accounts
WHERE opened_date >= '2023-06-20' AND YEAR(opened_date) >= 2023;

select id, store_name, coalesce(sqft, 0) as sqft_filled
from stores
where city in ('Chiang Mai', 'London', 'Tokyo') and sqft != 15456;

SELECT id, duration_sec, COALESCE(duration_sec, 0) AS duration_sec_filled
FROM web_events
WHERE duration_sec <= 178 AND event_type NOT IN ('page_view', 'click');

SELECT *, UPPER(city) AS city_upper, CASE WHEN country IN ('UK', 'DE') THEN 'Priority' ELSE 'Other' END AS country_group
FROM suppliers
WHERE country != 'DE';
